// deterministic stand-in for SHA-256(public_key) -> base64url(jkt)
function thumb(s){let x=2166136261>>>0;for(let i=0;i<s.length;i++){x^=s.charCodeAt(i);x=Math.imul(x,16777619)>>>0;}return ('00000000'+x.toString(16)).slice(-8);}
// the access token was issued bound to the legit client's public key
const tokenCnfJkt=thumb('client-pubkey-A');
// resource server: thumbprint of the key in the DPoP proof must equal token cnf.jkt
function verify(presentedKey){return thumb(presentedKey)===tokenCnfJkt?'ACCEPT':'REJECT';}
const out=[];
out.push('token cnf.jkt = '+tokenCnfJkt);
out.push('legit client (client-pubkey-A): '+verify('client-pubkey-A'));
out.push('attacker (attacker-pubkey-Z): '+verify('attacker-pubkey-Z'));
out.push('attacker (forged-key): '+verify('forged-key'));
console.log(out.join('\n'));

